const body = $input.item.json.body || $input.item.json;

const entry = body.entry?.[0];
const changes = entry?.changes?.[0];
const value = changes?.value;
const message = value?.messages?.[0];

if (!message) {
  return [{ json: { skip: true } }];
}

const telefono = message.from;
const texto = message.text?.body || '';
const messageId = message.id;
const timestamp = message.timestamp;
const nombreContacto = value?.contacts?.[0]?.profile?.name || '';
const tipoMensaje = message.type || 'text';
let mediaId = null, mimeType = null, mediaCaption = '';
if (['image','audio','document','video'].includes(tipoMensaje)) {
  const mediaObj = message[tipoMensaje] || {};
  mediaId = mediaObj.id || null;
  mimeType = mediaObj.mime_type || null;
  mediaCaption = mediaObj.caption || '';
}
const phoneNumberId = value?.metadata?.phone_number_id || '';

// FIX: Deduplicación — Meta envía el mismo webhook dos veces
// Usamos static data para recordar messageIds procesados en los últimos 60s
const staticData = $getWorkflowStaticData('global');
if (!staticData.seenMessageIds) staticData.seenMessageIds = {};

const now = Date.now();
// Limpiar entradas viejas (> 60 segundos)
Object.keys(staticData.seenMessageIds).forEach(id => {
  if (now - staticData.seenMessageIds[id] > 60000) delete staticData.seenMessageIds[id];
});

if (staticData.seenMessageIds[messageId]) {
  // Mensaje duplicado — ignorar
  return [{ json: { skip: true, skipReason: 'duplicate_messageId' } }];
}
staticData.seenMessageIds[messageId] = now;

return [{
  json: {
    telefono,
    texto,
    messageId,
    timestamp,
    nombreContacto,
    tipoMensaje,
    mediaId,
    mimeType,
    mediaCaption,
    phoneNumberId,
    skip: false
  }
}];

// Reconstrucción de base (27-ago): el fetch original (GET /api/n8n/companies/{id}/wa/leads
// con hours_inactive/status) nunca funcionó — ese endpoint exige un teléfono puntual, no
// sirve para listar. Reemplazado por /api/whatsapp/conversations (confirmado funcionando).
// El estado "ya se mandó/ya se notificó" tampoco se podía trackear por clasificacion (se
// descarta en silencio) — ahora vive en datos_calificacion, con lectura-mezcla-escritura
// para no borrar los datos reales que Marco ya recolectó del cliente.
const cData = $('📋 Obtener Conversaciones (Follow-up)').first().json;
const conversaciones = (cData && cData.data) || [];

const boardData = $('📋 Obtener CRM Board (Follow-up)').first().json;
// Mapa wa_contact_id -> etapa real del negocio, para no auto-seguir leads que ya
// gestiona una persona (negociación en curso, cerrado o perdido).
const etapaPorContacto = {};
if (boardData && typeof boardData === 'object') {
  for (const [etapa, deals] of Object.entries(boardData)) {
    if (!Array.isArray(deals)) continue;
    for (const d of deals) {
      if (d.wa_contact_id) etapaPorContacto[d.wa_contact_id] = etapa;
    }
  }
}
const etapasBloqueadas = ['closed', 'lost', 'negotiation', 'proposal'];

const now = new Date();
const results = [];

for (const conv of conversaciones) {
  const contact = conv.contact || {};
  const waContactId = conv.wa_contact_id || contact.id;
  const etapa = etapaPorContacto[waContactId];
  if (etapa && etapasBloqueadas.includes(etapa)) continue;

  const dc = contact.datos_calificacion || {};
  if (dc.followup_notificado) continue; // ya se hizo todo lo posible con este lead

  const ultimaInteraccion = new Date(conv.updated_at || conv.created_at);
  const horasDiff = (now - ultimaInteraccion) / (1000 * 60 * 60);

  let tipoAccion = null;
  if (!dc.followup_23h_enviado_en && horasDiff >= 23) {
    tipoAccion = 'enviar_23h';
  } else if (dc.followup_23h_enviado_en) {
    const horasDesdeEnvio = (now - new Date(dc.followup_23h_enviado_en)) / (1000 * 60 * 60);
    // ~49h desde el envío del primer follow-up ≈ 72h reales desde el silencio original.
    if (!isNaN(horasDesdeEnvio) && horasDesdeEnvio >= 49) tipoAccion = 'notificar';
  }

  if (tipoAccion) {
    results.push({ json: {
      telefono: (contact.phone || '').replace(/^\+/, ''),
      nombre: contact.name || 'cliente',
      tipoAccion,
      datosCalificacionActuales: dc
    } });
  }
}
return results;

