parameters.jsCode:
const ext = $('🔧 Extraer Mensaje y Teléfono').first().json;
let textoFinal = ext.texto;
try {
  const medio = $('🔧 Combinar Texto de Medio').first().json;
  if (medio && medio.texto) textoFinal = medio.texto;
} catch (e) {
  // No vino por la rama de medios (mensaje de texto normal) — usar texto tal cual, comportamiento original.
}
return [{ json: { telefono: ext.telefono, texto: textoFinal, nombreContacto: ext.nombreContacto || '' } }];

const ctx = $('▶️ 03 Generador IA').first().json;
const d = ctx.datosRecolectados || {};

// Only show price if all data collected and not already sent
// Use proximoPaso from 01 Clasificador as source of truth — includes all checks (correo, proteccion, etc.)
if (!ctx.todosRecolectados || ctx.cotizacionEnviada) {
  return [{ json: { ...ctx, precio: d.precio_cotizado || null } }];
}

// Read precio from HTTP node result
const apiResp = $input.first().json;
const precio = apiResp?.data?.precio_total || apiResp?.precio_total || null;

const idioma = ctx.idiomaConversacion || 'español';
const nombre = d.nombre_cliente ? `, ${d.nombre_cliente.split(' ')[0]}` : '';
const tieneProteccion = d.proteccion_extra === true || d.proteccion_extra === 'true';

let mensajeFinal;
if (precio) {
  if (idioma === 'inglés') {
    mensajeFinal = `Here is your estimate${nombre}! 🎉\n\n📦 *${d.producto || 'Crate'}*\n📐 Dimensions: ${d.medidas || '—'}"\n🗓 Needed by: ${d.fecha || '—'}\n🛡 Extra protection: ${tieneProteccion ? 'Yes' : 'No'}\n\n💵 *Estimated price: $${precio} USD*\n_This is an estimate. The final price may vary after inspection._\n\nWould you like a formal quote sent to your email?`;
  } else {
    mensajeFinal = `¡Aquí está tu estimado${nombre}! 🎉\n\n📦 *${d.producto || 'Cajón'}*\n📐 Medidas: ${d.medidas || '—'}"\n🗓 Para: ${d.fecha || '—'}\n🛡 Protección extra: ${tieneProteccion ? 'Sí' : 'No'}\n\n💵 *Precio estimado: $${precio} USD*\n_Este es un estimado. El precio final puede variar luego de la inspección._\n\n¿Le gustaría que le enviemos la cotización formal a su correo?`;
  }
} else {
  mensajeFinal = ctx.mensaje;
}

return [{ json: {
  ...ctx,
  datosRecolectados: { ...d, precio_cotizado: precio || d.precio_cotizado || null },
  mensaje: mensajeFinal,
  mensajeRespuesta: mensajeFinal,
  cotizadorEnviado: !!precio,
  precio: precio || d.precio_cotizado || null
} }];

const ctx = $input.first().json;
const t = (ctx.texto || '').toLowerCase();
const enWords = (t.match(/\b(i|the|you|need|have|want|please|thanks|yes|for|and|my|is|are|can|would|like|to|of|in|with|it|this|that|hi|hello|good|morning|afternoon|evening|crate|inches|inch|by|next|about|looking|want|send|ship|pack|protection|foam|email|quote|price|we|our|us|them|they|what|when|where|how|who|why|get|make|do|go|come|take|give|use|find|know|see|look|think|work|call|ask|tell|help|keep|let|put|seem|feel|try|leave|still|start|might|could|should|would|same|well|just|over|back|after|before|also|been|here|there|then|than|these|those|more|most|some|such|only|both|too|very|much|many|your|their|her|his|him|her|she|he|it|we|them|will|was|were|had|has|have|did|does|do|am|be|been|being|an|a|at|from|by|with|out|up|down|off|on|into|through|during|before|after|above|below|between|each|few|more|most|other|some|such|than|too|very|just|because|as|until|while|although|whether|either|neither|however|therefore|meanwhile|furthermore|accordingly|consequently|subsequently)\b/g) || []).length;
const esWords = (t.match(/\b(quiero|necesito|tengo|hola|gracias|por|sí|si|no|para|con|una|un|que|me|mi|el|la|los|las|de|en|es|son|buenas|buenos|embalar|cajón|cerrado|abierto|medidas|correo|cotización|precio|protección|espuma|soy|como|pero|cuando|donde|quien|este|esta|esto|también|muy|más|porque|ser|estar|hacer|poder|tener|deber|querer|hay|fue|era|han|del|al|le|se|lo|ya|cada|todo|toda|todos|todas|algo|alguien|nadie|nunca|siempre|antes|después|aquí|allí|ahora|luego|hoy|mañana|ayer|semana|mes|año|tiempo|momento|forma|lugar|parte|caso|tipo|manera|favor|empresa|trabajo|equipo|cliente|servicio)\b/g) || []).length;
const esIngles = enWords > esWords && enWords >= 2;
return [{ json: { ...ctx, idiomaOriginal: esIngles ? 'inglés' : 'español', textoOriginal: ctx.texto } }];

const prev = $('🌐 Detectar Idioma Entrada').first().json;
const raw = $input.first().json;
const traducido = raw.choices?.[0]?.message?.content?.trim() || prev.textoOriginal;
return [{ json: { ...prev, texto: traducido } }];

const armar = $('📝 Armar Mensaje Final').first().json;
const tradResp = $input.first().json;
// Extract translated text from Groq response
const traducido = tradResp.choices?.[0]?.message?.content?.trim();
const mensajeFinal = traducido || armar.mensajeRespuesta || armar.mensaje || '';
return [{ json: { ...armar, mensaje: mensajeFinal, mensajeRespuesta: mensajeFinal } }];

const resultado = $input.first().json;
const tipo = $('🔧 Extraer Mensaje y Teléfono').first().json.tipoMensaje || 'archivo';
const etiquetas = { image: 'imagen', audio: 'audio', document: 'documento', video: 'video' };
const prefijo = `[Cliente envió ${etiquetas[tipo] || 'un archivo'}] `;
const textoProcesado = (resultado && !resultado.error && resultado.texto) ? resultado.texto : '[No se pudo procesar el archivo enviado]';
return [{ json: { texto: prefijo + textoProcesado } }];

const ext = $('🔧 Extraer Mensaje y Teléfono').first().json;
return [{ json: {
  media_id: ext.mediaId,
  mime_type: ext.mimeType,
  caption: ext.mediaCaption,
  phone_number_id: ext.phoneNumberId,
  gemini_api_key: ''
} }];

const board = $('📋 G54: Buscar Deal Existente (CRM Marco)').item.json;
const telefono = $('📝 Armar Mensaje Final').item.json.telefono || '';

let match = null;
try {
  for (const etapa of Object.keys(board)) {
    const deals = board[etapa] || [];
    const found = deals.find(d => d.telefono === telefono);
    if (found) { match = found; break; }
  }
} catch (e) { /* si el board no cargó, seguimos como si no existiera */ }

let wa_contact_id = null;
try {
  const contactData = $('🔍 Buscar Contact ID (CRM Marco)').item.json.data || [];
  wa_contact_id = contactData[0]?.id || null;
} catch (e) { /* si falló el lookup, seguimos sin el vínculo */ }

return [{ json: {
  existe: !!match,
  deal_id: match ? match.id : null,
  telefono,
  wa_contact_id,
}}];

const dealResp = $json;
const dealId = dealResp && dealResp.id ? dealResp.id : null;

let contenido = null;
try {
  const armado = $('📝 Armar Mensaje Final').item.json;
  const clasificacion = armado.clasificacion || '';
  if (clasificacion === 'Caliente') {
    contenido = 'Marco: cliente aceptó cotización, clasificado como lead caliente.';
  } else if (clasificacion === 'Consulta') {
    contenido = 'Marco: consulta escalada a un especialista.';
  }
} catch (e) { /* si no se puede leer, no se loggea nada */ }

return [{ json: { dealId, contenido, deberiaLoggear: !!(dealId && contenido) } }];

